('46ecc488-b16d-4cd1-9861-c0c75eefaa0f', 'c744e096-dd79-41a4-bd40-a6cfc457d429', '81994d17-2d87-4b3a-9f58-5fd2909a741e', '1', '6', 'angka', 'SD', 'Kuis Pecahan Sederhana', 'Lima soal pecahan dasar.', '60', '[{"id": "0808f756-20a8-4b3e-8865-560ee20d4a5e", "answer": 1, "prompt": "Sebuah pizza dipotong menjadi 4 bagian sama besar. Kamu makan 1 potong. Pecahan yang menyatakan bagianmu adalah ...", "options": ["1/2", "1/4", "1/3", "4/1"], "explanation": "Satu dari empat bagian sama besar ditulis 1/4."}, {"id": "d189f196-618f-4945-8730-a5144b22ca94", "answer": 1, "prompt": "Pada pecahan 3/5, angka 5 disebut ...", "options": ["pembilang", "penyebut", "hasil", "selisih"], "explanation": "Angka di bawah garis adalah penyebut."}, {"id": "28a651fa-116f-4c7d-a912-24fad33e4a35", "answer": 2, "prompt": "Manakah pecahan yang paling besar?", "options": ["1/8", "1/4", "1/2", "1/3"], "explanation": "Pembilang sama, penyebut makin kecil nilainya makin besar."}, {"id": "39bd7679-894d-461e-8bcb-19aa75635567", "answer": 1, "prompt": "2/6 sama nilainya dengan ...", "options": ["1/2", "1/3", "2/3", "3/6"], "explanation": "Bagi pembilang dan penyebut dengan 2: 2/6 = 1/3."}, {"id": "8766ded9-f96e-4878-857f-3760773dccdb", "answer": 2, "prompt": "Ibu membagi 8 kue sama banyak untuk 2 anak. Setiap anak mendapat pecahan ... dari seluruh kue.", "options": ["1/8", "1/4", "1/2", "2/8 bagian"], "explanation": "Dua bagian sama besar, tiap anak mendapat 1/2."}]', '2026-11-20 07:07:56.834852+00:00'),
('d055dc24-fa31-4e42-91e6-28a779653111', 'c744e096-dd79-41a4-bd40-a6cfc457d429', '40fd8dc6-5a32-4f53-9062-65489deca316', '1', '7', 'angka', 'SMP', 'Kuis Bilangan Bulat', 'Enam soal operasi bilangan bulat.', '70', '[{"id": "72f037d9-c20d-49b2-a60f-31f69b4e3eac", "answer": 2, "prompt": "Hasil dari -7 + 10 adalah ...", "options": ["-17", "-3", "3", "17"], "explanation": "Dari -7 bergerak 10 ke kanan menjadi 3."}, {"id": "9f35ffc8-3041-44b3-9317-c5fe94b42709", "answer": 2, "prompt": "Hasil dari 5 - (-4) adalah ...", "options": ["1", "-1", "9", "-9"], "explanation": "Mengurang negatif sama dengan menjumlah: 5 + 4 = 9."}, {"id": "a2fd6127-33fb-4d03-9ae5-90748696d749", "answer": 0, "prompt": "Urutan dari yang terkecil: ...", "options": ["-3, -1, 0, 2", "0, -1, -3, 2", "2, 0, -1, -3", "-1, -3, 0, 2"], "explanation": "Pada garis bilangan, makin ke kiri makin kecil."}, {"id": "96edefad-bea7-43ba-a603-39035a1809ee", "answer": 2, "prompt": "Suhu pagi -2 derajat dan siang naik 9 derajat. Suhu siang adalah ...", "options": ["-11", "-7", "7", "11"], "explanation": "-2 + 9 = 7."}, {"id": "21d3fc47-d9e0-4a28-90ad-cce3e69dd5f9", "answer": 0, "prompt": "Hasil dari -6 - 4 adalah ...", "options": ["-10", "-2", "2", "10"], "explanation": "-6 - 4 = -6 + (-4) = -10."}, {"id": "fb77f704-18cd-4f99-8b03-07e710e660d1", "answer": 2, "prompt": "Lawan dari bilangan -15 adalah ...", "options": ["-15", "0", "15", "1/15"], "explanation": "Lawan suatu bilangan memiliki nilai sama dengan tanda berbeda."}]', '2026-11-20 07:07:56.923617+00:00'),
('adeedd82-0f78-4159-93ee-61e6babaecb9', 'c744e096-dd79-41a4-bd40-a6cfc457d429', '54a0f648-02e2-4264-9e60-3eebe8dd4c66', '1', '7', 'sains', 'SD', 'Kuis Tata Surya', 'Enam soal tentang Matahari dan planet.', '60', '[{"id": "7e71bba6-c3d6-423b-b330-4ba3efb51c86", "answer": 2, "prompt": "Pusat Tata Surya adalah ...", "options": ["Bumi", "Bulan", "Matahari", "Mars"], "explanation": "Semua planet mengelilingi Matahari."}, {"id": "62e6fd63-11c4-4a8d-ba2e-45764e039b8e", "answer": 1, "prompt": "Planet terdekat dengan Matahari adalah ...", "options": ["Venus", "Merkurius", "Mars", "Bumi"], "explanation": "Urutan dari Matahari: Merkurius, Venus, Bumi, Mars."}, {"id": "7dab63c8-7806-4942-a1ef-9534b49bd735", "answer": 1, "prompt": "Berapa banyak planet di Tata Surya?", "options": ["7", "8", "9", "10"], "explanation": "Ada delapan planet."}, {"id": "d4f1a367-8576-4e8e-9f81-1b03397ba4f7", "answer": 1, "prompt": "Siang dan malam terjadi karena ...", "options": ["Bumi mengelilingi Matahari", "Bumi berputar pada porosnya", "Bulan menutupi Matahari", "Matahari berputar"], "explanation": "Rotasi Bumi selama sekitar 24 jam."}, {"id": "3e42b6b4-93cd-4263-a86f-388763310916", "answer": 2, "prompt": "Planet terbesar di Tata Surya adalah ...", "options": ["Saturnus", "Neptunus", "Yupiter", "Uranus"], "explanation": "Yupiter adalah planet raksasa gas terbesar."}, {"id": "bfc1564e-214d-4871-8fe3-94b178cd3b6e", "answer": 2, "prompt": "Satu tahun di Bumi lamanya sekitar ...", "options": ["30 hari", "100 hari", "365 hari", "720 hari"], "explanation": "Waktu Bumi mengelilingi Matahari sekali."}]', '2026-11-20 07:07:56.996394+00:00'),
('44c86239-e5a5-41a4-987d-4ffdfc619db7', 'c744e096-dd79-41a4-bd40-a6cfc457d429', '64cf94fa-8a57-40ad-8043-52caa6b30fa7', '1', '7', 'sains', 'SMP', 'Kuis Ekosistem', 'Enam soal rantai makanan.', '70', '[{"id": "dae7bdb8-6599-46e5-a45f-81dac1efda50", "answer": 1, "prompt": "Makhluk hidup yang membuat makanan sendiri disebut ...", "options": ["konsumen", "produsen", "pengurai", "parasit"], "explanation": "Tumbuhan hijau membuat makanan lewat fotosintesis."}, {"id": "6b3b7ae2-3d87-4c4d-a865-35464ebb7107", "answer": 2, "prompt": "Pada rantai: rumput, belalang, katak, ular, siapa konsumen tingkat dua?", "options": ["rumput", "belalang", "katak", "ular"], "explanation": "Katak memakan belalang (konsumen tingkat satu)."}, {"id": "6151c805-5ada-4180-a1f1-256d0c732eac", "answer": 2, "prompt": "Jamur dan bakteri berperan sebagai ...", "options": ["produsen", "herbivora", "pengurai", "karnivora"], "explanation": "Pengurai menguraikan sisa makhluk hidup."}, {"id": "bed419a8-94fa-4f5e-aa0c-47590a642599", "answer": 1, "prompt": "Hewan pemakan tumbuhan disebut ...", "options": ["karnivora", "herbivora", "omnivora", "detritivor"], "explanation": "Herbivora hanya memakan tumbuhan."}, {"id": "c7cde8bd-4009-4b8f-9c1b-86fc3d892d87", "answer": 2, "prompt": "Sumber energi utama hampir semua rantai makanan adalah ...", "options": ["air", "tanah", "Matahari", "angin"], "explanation": "Matahari memberi energi untuk fotosintesis."}, {"id": "283a5f4d-64a3-40a9-8bb4-26e7b5647c80", "answer": 1, "prompt": "Mengapa jumlah pemangsa puncak sedikit?", "options": ["Mereka malas berburu", "Energi yang diteruskan makin kecil di tiap tingkat", "Mereka tidak butuh makan", "Tumbuhan beracun"], "explanation": "Sebagian besar energi hilang sebagai panas pada tiap tingkat."}]', '2026-11-20 07:07:57.078122+00:00'),
