('a8cbb96d-bea0-4f6e-83bc-8296a0207fc8', 'c744e096-dd79-41a4-bd40-a6cfc457d429', 'c66d3bd5-6324-442b-8364-16754a83bc68', '1', '7', 'galeri', 'SMA', 'Kuis Proklamasi Kemerdekaan', 'Enam soal sejarah proklamasi.', '70', '[{"id": "c4f8438a-5e56-44f5-9f43-e82c0245b64f", "answer": 0, "prompt": "Proklamasi kemerdekaan Indonesia dibacakan pada tanggal ...", "options": ["17 Agustus 1945", "1 Juni 1945", "28 Oktober 1928", "10 November 1945"], "explanation": "Hari Jumat, 17 Agustus 1945."}, {"id": "f1599a65-831d-4bc4-8e58-7715555fd253", "answer": 1, "prompt": "Teks proklamasi diketik oleh ...", "options": ["Mohammad Hatta", "Sayuti Melik", "Ahmad Soebardjo", "Sukarni"], "explanation": "Sayuti Melik mengetik naskah yang disepakati."}, {"id": "d4d7be43-c3c7-44ce-8978-8886177ac1dc", "answer": 0, "prompt": "Peristiwa para pemuda membawa Soekarno-Hatta keluar Jakarta disebut ...", "options": ["Peristiwa Rengasdengklok", "Peristiwa Surabaya", "Sumpah Pemuda", "Konferensi Meja Bundar"], "explanation": "Pemuda mendesak agar proklamasi dipercepat."}, {"id": "0e819f5b-79c6-4658-963f-fdd0477cdfc8", "answer": 2, "prompt": "Teks proklamasi disusun di rumah ...", "options": ["Soekarno", "Hatta", "Laksamana Maeda", "Sutan Sjahrir"], "explanation": "Rumah Laksamana Tadashi Maeda di Jakarta."}, {"id": "8f86e225-3cc3-4df1-890b-a01f9af78372", "answer": 0, "prompt": "Jepang menyerah kepada Sekutu pada ...", "options": ["15 Agustus 1945", "17 Agustus 1945", "1 Maret 1942", "2 September 1945"], "explanation": "Menyerah pada 15 Agustus 1945."}, {"id": "76cb3521-bee4-40e3-8961-4cb5bbbd2444", "answer": 1, "prompt": "Proklamasi dibacakan di ...", "options": ["Gedung Merdeka", "Jalan Pegangsaan Timur 56", "Lapangan Ikada", "Istana Negara"], "explanation": "Di halaman rumah Soekarno, Pegangsaan Timur 56."}]', '2026-11-20 07:08:21.461505+00:00');
