  CONSTRAINT "modules_level_check" CHECK (level = ANY (ARRAY['SD'::text, 'SMP'::text, 'SMA'::text, 'Umum'::text])),
  CONSTRAINT "modules_title_check" CHECK (char_length(title) >= 1 AND char_length(title) <= 120)
);


CREATE TABLE "public"."quiz_attempts" (
  "id" uuid NOT NULL,
  "org_id" uuid NOT NULL,
  "quiz_id" uuid NOT NULL,
  "user_id" uuid NOT NULL,
  "questions" jsonb NOT NULL,
  "answers" smallint[] NOT NULL,
  "pass_score" smallint NOT NULL,
  "started_at" timestamp with time zone NOT NULL,
  "finished_at" timestamp with time zone,
  "correct" smallint,
  "score" smallint,
  "assignment_id" uuid,
  "assignment_step_id" uuid,
  "quiz_revision_id" uuid,
  "module_id" uuid,
  "module_revision_id" uuid,
  CONSTRAINT "quiz_attempts_pkey" PRIMARY KEY (id),
  CONSTRAINT "quiz_attempts_assignment_context" CHECK ((assignment_id IS NULL) = (assignment_step_id IS NULL)),
  CONSTRAINT "quiz_attempts_check" CHECK (jsonb_typeof(questions) = 'array'::text AND jsonb_array_length(questions) = cardinality(answers)),
  CONSTRAINT "quiz_attempts_check1" CHECK ((finished_at IS NULL) = (score IS NULL) AND (score IS NULL) = (correct IS NULL)),
  CONSTRAINT "quiz_attempts_correct_check" CHECK (correct >= 0),
  CONSTRAINT "quiz_attempts_pass_score_check" CHECK (pass_score >= 1 AND pass_score <= 100),
  CONSTRAINT "quiz_attempts_score_check" CHECK (score >= 0 AND score <= 100)
);


CREATE TABLE "public"."quiz_questions" (
  "id" uuid NOT NULL,
  "org_id" uuid NOT NULL,
  "quiz_id" uuid NOT NULL,
  "position" integer NOT NULL,
  "prompt" text NOT NULL,
  "options" text[] NOT NULL,
  "answer" smallint NOT NULL,
  "explanation" text NOT NULL DEFAULT ''::text,
  "created_at" timestamp with time zone NOT NULL,
  "updated_at" timestamp with time zone NOT NULL,
  CONSTRAINT "quiz_questions_pkey" PRIMARY KEY (id),
  CONSTRAINT "quiz_questions_answer_check" CHECK (answer >= 0 AND answer < cardinality(options)),
  CONSTRAINT "quiz_questions_explanation_check" CHECK (char_length(explanation) <= 500),
  CONSTRAINT "quiz_questions_options_check" CHECK ((cardinality(options) = ANY (ARRAY[2, 4])) AND array_position(options, NULL::text) IS NULL),
  CONSTRAINT "quiz_questions_position_check" CHECK ("position" >= 0),
  CONSTRAINT "quiz_questions_prompt_check" CHECK (char_length(prompt) >= 1 AND char_length(prompt) <= 500)
);



CREATE TABLE "public"."quiz_revisions" (
  "id" uuid NOT NULL,
  "org_id" uuid NOT NULL,
  "quiz_id" uuid NOT NULL,
  "revision" integer NOT NULL,
  "draft_version" bigint NOT NULL,
  "building_key" text NOT NULL,
  "level" text NOT NULL,
  "title" text NOT NULL,
  "description" text NOT NULL,
  "pass_score" smallint NOT NULL,
  "questions" jsonb NOT NULL,
  "published_at" timestamp with time zone NOT NULL,
  CONSTRAINT "quiz_revisions_pkey" PRIMARY KEY (id),
  CONSTRAINT "quiz_revisions_org_id_quiz_id_id_key" UNIQUE (org_id, quiz_id, id),
  CONSTRAINT "quiz_revisions_quiz_id_draft_version_key" UNIQUE (quiz_id, draft_version),
  CONSTRAINT "quiz_revisions_quiz_id_revision_key" UNIQUE (quiz_id, revision),
  CONSTRAINT "quiz_revisions_pass_score_check" CHECK (pass_score >= 1 AND pass_score <= 100),
  CONSTRAINT "quiz_revisions_questions_check" CHECK (jsonb_typeof(questions) = 'array'::text),
  CONSTRAINT "quiz_revisions_revision_check" CHECK (revision > 0)
);


CREATE TABLE "public"."quizzes" (
  "id" uuid NOT NULL,
  "org_id" uuid NOT NULL,
  "building_key" text NOT NULL,
  "level" text NOT NULL,
  "title" text NOT NULL,
  "description" text NOT NULL DEFAULT ''::text,
  "pass_score" smallint NOT NULL DEFAULT 60,
  "created_by" uuid NOT NULL,
  "created_at" timestamp with time zone NOT NULL,
  "updated_at" timestamp with time zone NOT NULL,
  "published_at" timestamp with time zone,
  "archived_at" timestamp with time zone,
  "draft_version" bigint NOT NULL DEFAULT 1,
  "published_revision_id" uuid,
  CONSTRAINT "quizzes_pkey" PRIMARY KEY (id),
  CONSTRAINT "quizzes_org_id_id_key" UNIQUE (org_id, id),
  CONSTRAINT "quizzes_building_key_check" CHECK (char_length(building_key) >= 1 AND char_length(building_key) <= 40),
  CONSTRAINT "quizzes_description_check" CHECK (char_length(description) <= 500),
  CONSTRAINT "quizzes_draft_version_check" CHECK (draft_version > 0),
  CONSTRAINT "quizzes_level_check" CHECK (level = ANY (ARRAY['SD'::text, 'SMP'::text, 'SMA'::text, 'Umum'::text])),
  CONSTRAINT "quizzes_pass_score_check" CHECK (pass_score >= 1 AND pass_score <= 100),
  CONSTRAINT "quizzes_title_check" CHECK (char_length(title) >= 1 AND char_length(title) <= 120)
);


CREATE TABLE "public"."reports" (
  "id" uuid NOT NULL DEFAULT gen_random_uuid(),
  "org_id" uuid NOT NULL,
  "room_id" uuid,
