DO E'BEGIN EXECUTE ''ALTER SEQUENCE '' || pg_get_serial_sequence(''"public"."chat_messages"'', ''id'') || E''\\n  AS bigint\\n  START WITH 1\\n  INCREMENT BY 1\\n  MINVALUE 1\\n  MAXVALUE 9223372036854775807\\n  CACHE 1\\n  NO CYCLE RESTART WITH 1''; END;';

DO E'BEGIN EXECUTE ''ALTER SEQUENCE '' || pg_get_serial_sequence(''"public"."goose_db_version"'', ''id'') || E''\\n  AS integer\\n  START WITH 1\\n  INCREMENT BY 1\\n  MINVALUE 1\\n  MAXVALUE 2147483647\\n  CACHE 1\\n  NO CYCLE RESTART WITH 1''; END;';

SELECT setval(pg_get_serial_sequence('"public"."chat_messages"', 'id'), GREATEST(COALESCE(MAX("id"), 32), 32), true) FROM "public"."chat_messages";

SELECT setval(pg_get_serial_sequence('"public"."goose_db_version"', 'id'), GREATEST(COALESCE(MAX("id"), 25), 25), true) FROM "public"."goose_db_version";

CREATE OR REPLACE FUNCTION public.protect_content_revision()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN RAISE EXCEPTION 'published content is immutable'; END;
$function$;

CREATE OR REPLACE FUNCTION public.reject_guest_account_access()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF EXISTS (SELECT 1 FROM users WHERE id = NEW.user_id AND is_guest) THEN
        RAISE EXCEPTION 'guest cannot receive account access' USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$function$;

